use glam::Vec3;
use serde::Deserialize;
#[derive(Clone,Copy,Deserialize)]#[serde(default)]
pub struct PitchConfig{pub sprite_pitch_factor:f32,pub sprite_pitch_max_deg:f32,pub sprite_pitch_smoothing_seconds:f32,pub sprite_yaw_zenith_hold_cos:f32,pub sprite_yaw_max_speed_deg:f32}
impl Default for PitchConfig{fn default()->Self{Self{sprite_pitch_factor:0.45,sprite_pitch_max_deg:30.0,sprite_pitch_smoothing_seconds:0.1,sprite_yaw_zenith_hold_cos:0.07,sprite_yaw_max_speed_deg:360.0}}}
#[derive(Clone,Copy,Default)]pub struct Facing{pub pitch:f32,pub yaw:f32,pub elevation:f32,pub initialized:bool}
impl Facing{pub fn update(&mut self,d:Vec3,dt:f32,c:PitchConfig,structure:bool){let horizontal=d.x.hypot(d.z);let elevation=d.y.max(0.0).atan2(horizontal);let pitch=(c.sprite_pitch_factor*elevation).min(c.sprite_pitch_max_deg.to_radians())*if structure{0.5}else{1.0};let yaw=if d.length()>0.00001&&horizontal/d.length()>c.sprite_yaw_zenith_hold_cos{d.x.atan2(d.z)}else{self.yaw};if !self.initialized{self.pitch=pitch;self.yaw=yaw;self.initialized=true;}else{let blend=1.0-(-dt.clamp(0.0,0.1)/c.sprite_pitch_smoothing_seconds.max(0.001)).exp();self.pitch+=(pitch-self.pitch)*blend;let step=(yaw-self.yaw).sin().atan2((yaw-self.yaw).cos())*blend;let max_yaw=c.sprite_yaw_max_speed_deg.to_radians()*dt.clamp(0.0,0.1);self.yaw+=step.clamp(-max_yaw,max_yaw);}self.elevation=elevation;}}
#[cfg(test)]mod tests{use super::*;#[test]fn pitch_targets_and_zenith(){let c=PitchConfig::default();for(deg,expected)in[(10.0f32,4.5f32),(30.0,13.5),(45.0,20.25),(60.0,27.0),(80.0,30.0)]{let mut f=Facing::default();f.update(Vec3::new(0.0,deg.to_radians().sin(),deg.to_radians().cos()),0.01,c,false);assert!((f.pitch.to_degrees()-expected).abs()<0.001);}let mut f=Facing::default();f.update(Vec3::new(0.01,1.0,1.0),0.1,c,false);let yaw=f.yaw;f.update(Vec3::new(-0.00001,1.0,-0.00001),0.1,c,false);assert!((f.yaw-yaw).abs()<1e-6);}}
